import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';
const root=process.cwd(),P='plans/260925-documentation-authority-unification',R=P+'/reports/phase-07',F='8b2ee4dd99fc89689f20274f1cfd5e1ad7a3469a';
const gen=await import(path.join(root,'scripts/generate-doc-inventory.mjs'));const read=f=>JSON.parse(fs.readFileSync(f,'utf8')),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const [input,select='all']=process.argv.slice(2);assert(input,'Usage: node row-auth.mjs <index-or-part.json> [entry|all]');
const index=read(input),parts=index.parts?index.parts.map(p=>path.join(path.dirname(input),p.path)):[input],queue=read(R+'/step-09-rebind-units.json'),registry=read(P+'/reports/phase-06/working-identity-registry.json');
const native=new Map(['units','identityGaps','retiredUnits'].flatMap(c=>registry[c].map(u=>[u.claimId,{c,u}])));let oldRegistry,raw,rebind,listChanges,metadata,history;const cache=new Map();
const old=()=>oldRegistry??=JSON.parse(execFileSync('git',['show',F+':'+P+'/reports/phase-06/working-identity-registry.json'],{maxBuffer:100*1024*1024}));
const units=(pin,p)=>{const k=pin+':'+p;if(!cache.has(k)){const s=execFileSync('git',['show',k],{encoding:'utf8',maxBuffer:20*1024*1024});cache.set(k,p.endsWith('.md')?gen.extractMarkdownConservationUnits(s):gen.extractMixedFileConservationUnit(p,s));}return cache.get(k);};
const tuple=u=>Object.fromEntries(['claimId','sourcePath','sourceAnchor','sourceUnitDigest'].map(k=>[k,u[k]]));
const checkBinding=b=>{if(b.encoding.startsWith('exact UTF-8 line')){const line=fs.readFileSync(b.path,'utf8').split(/\r?\n/)[b.selector.line-1];assert.equal(sha(line),b.digest);assert.equal(line,b.content);}
else if(b.encoding.startsWith('canonical compact JSON')){const j=read(b.path),v=j[b.selector.array].find(r=>r.id===b.selector.id);assert.deepEqual(v,b.content);assert.equal(sha(JSON.stringify(v)),b.digest);}
else {const us=units(F,b.path);if(b.selector.anchor){assert.equal(us.find(u=>u.anchor===b.selector.anchor)?.textDigest,b.digest);}else{const digests=b.selector.anchors.map(a=>us.find(u=>u.anchor===a)?.textDigest);assert.deepEqual(digests,b.unitDigests);assert.equal(sha(JSON.stringify(digests)),b.digest);}}};
const auth=e=>{switch(e.kind){
case 'current':case 'displaced':{const [field,n]=e.queue,t=queue[field][n];assert.deepEqual(t,e.tuple);assert.equal(queue.files[t[0]].path,e.path);const us=units(e.kind==='current'?F:queue.base,e.path),hits=us.filter(u=>u.anchor===t[2]&&u.textDigest===t[5]&&u.unitKind===t[1]);assert.equal(hits.length,1);const u=hits[0],i=us.indexOf(u);assert.equal(u.startLine,t[3]);assert.equal(u.endLine,t[4]);assert.equal(i?us[i-1].textDigest:null,e.context.previous);assert.equal(i+1<us.length?us[i+1].textDigest:null,e.context.next);const now=native.get(e.native.claimId);assert(now);assert.equal(now.c,e.nativeCollection);if(e.kind==='current')assert.deepEqual(tuple(now.u),e.native);else{const prev=old().units.find(u=>u.claimId===e.native.claimId);assert.deepEqual(tuple(prev),e.native);assert.deepEqual(tuple(now.u),e.currentNative);}break;}
case 'routing-binding':{checkBinding(e.binding.source);checkBinding(e.binding.target);const r=read(R+'/cross-area-inventory.json').rows.find(r=>r.rowId===e.entry);assert.equal(r.sourceDigest,e.binding.source.digest);assert.equal(r.targetDigest,e.binding.target.digest);assert.equal(r.reviewStatus,'pending');break;}
case 'decision':{rebind??=read(R+'/step-09-package-rebindings.json');const m=rebind.mutations[e.receiptIndex];assert.equal(m.claimId,e.claimId);const d=read(m.file)[m.collection].find(r=>JSON.stringify(r)===JSON.stringify(m.after));assert(d,'exact current decision row absent '+e.entry);assert.deepEqual(d,m.after);assert.equal(d.reviewStatus,'pending');for(const k of ['reviewedBy','reviewedAt','reviewReport','reviewReportCommit','reviewMode','reviewPackCommit','reviewPackId','seedScoreId','ordinaryAssessment'])assert.equal(d[k],undefined,'approval carry '+e.entry+' '+k);break;}
case 'native-change':{raw??=read(R+'/step-09-package-native-changes.json');const m=raw.changes[e.receiptIndex];assert.equal(m.claimId,e.claimId);const previous=m.beforeCollection?old()[m.beforeCollection].find(u=>u.claimId===e.claimId):null;assert.deepEqual(previous??null,m.before);const now=native.get(e.claimId);assert.equal(now?.c,m.afterCollection);if(now?.c==='retiredUnits'&&now.u.retiredAtCommit===F){const keys=['disposition','targetOwner','targetAnchor','reviewStatus','authoredBy','rationale'];const core=o=>Object.fromEntries(Object.entries(o).filter(([k])=>!keys.includes(k)));assert.deepEqual(core(now.u),core(m.after));assert.equal(now.u.reviewStatus,'pending');assert.equal(now.u.disposition,'retain-as-evidence');}else assert.deepEqual(now?.u??null,m.after);break;}
case 'candidate-list-rebind':{listChanges??=read(R+'/step-09-package-candidate-list-changes.json');const m=listChanges.removedHistoricalTuples[e.receiptIndex];const current=read(m.file).rows;assert(!current.some(r=>r.claimId===m.before.claimId&&r.path===m.before.path));break;}
case 'candidate-current':{const u=native.get(e.row.claimId);assert.equal(u?.c,'units');assert.equal(u.u.sourcePath,e.row.path);assert.equal(u.u.sourceAnchor,e.row.anchor);assert.equal(u.u.sourceUnitDigest,e.row.unitDigest);assert.equal(e.row.reviewStatus,'pending');break;}
case 'A34-join':{assert.deepEqual(tuple(native.get(e.native.claimId).u),e.native);assert.equal(sha(fs.readFileSync(e.residualFile)),e.residualSHA256);assert.equal(e.residualSHA256,e.priorResidualSHA256);break;}
case 'identical-owner-join':{const q=queue.affectedIdenticalOwnerGroups.groups.find(g=>g.digest===e.declaration.digest);assert.deepEqual(q,e.declaration);const current=read(R+'/step-09-package-identical-owner-bindings.json');assert.deepEqual(current.currentGroups,read(R+'/step-09-package-expected.json').identicalUnits);break;}
case 'N2':{assert.equal(sha(fs.readFileSync(e.path)),e.fileSHA256);const key='step-07-reader-key.md';assert.equal(sha(fs.readFileSync(R+'/'+key)),sha(execFileSync('git',['show',F+':'+R+'/'+key])));break;}
case 'native-document':{metadata??=read(R+'/step-09-package-native-metadata.json');const m=metadata.documentChanges[e.receiptIndex];assert.deepEqual(registry.documents.find(d=>d.path===m.path)??null,m.after);assert.deepEqual(old().documents.find(d=>d.path===m.path)??null,m.before);break;}
case 'native-metadata':{metadata??=read(R+'/step-09-package-native-metadata.json');assert.equal(sha(fs.readFileSync(P+'/reports/phase-06/working-identity-registry.json')),metadata.persistedRegistrySHA256);assert.equal(registry.commit,F);break;}
case 'historical':{history??=read(P+'/ledger/retired-unit-decisions.json');const d=history.rows.find(r=>r.claimId===e.claimId);assert(d);assert.equal(d.reviewStatus,'pending');assert.equal(d.targetOwner,null);assert.equal(d.targetAnchor,null);assert.equal(d.sourceUnitDigest,native.get(e.claimId).u.sourceUnitDigest);break;}
default:throw Error('Unsupported entry '+e.kind);}
};
let checked=0;for(const p of parts){const b=fs.readFileSync(p);if(index.parts){const meta=index.parts.find(x=>path.join(path.dirname(input),x.path)===p);assert.equal(b.length,meta.bytes);assert.equal(sha(b),meta.sha256);}const part=JSON.parse(b);assert(part.entries.length<=60);assert(b.length<=400000);for(const e of part.entries){if(select!=='all'&&e.entry!==select)continue;auth(e);checked++;}}
assert(checked>0);console.log(JSON.stringify({checked,mechanicalOnly:true,semanticReview:'pending; no verdict supplied'}));
